41	/// Check if we might be at an ATX header.
42	/// We only check if the current token is a HASH - full validation happens in parse_header.
43	pub(crate) fn at_header(p: &mut MarkdownParser) -> bool {
44	    p.lookahead(|p| {
45	        if !p.at_line_start() && !p.at_start_of_input() {
46	            return false;
47	        }
48	        p.skip_line_indent(MAX_BLOCK_PREFIX_INDENT);
49	        p.at(T![#])
50	    })
51	}
