587	/// Grammar: MdSetextHeader = content: MdInlineItemList underline: 'md_setext_underline_literal'
588	pub(crate) fn parse_paragraph(p: &mut MarkdownParser) -> ParsedSyntax {
589	    let m = p.start();
590	
591	    let inline_start: usize = p.cur_range().start().into();
592	    parse_inline_item_list(p);
593	    let inline_end: usize = p.cur_range().start().into();
594	
595	    let has_inline_content = inline_has_non_whitespace(p, inline_start, inline_end);
596	    let allow_setext = has_inline_content && allow_setext_heading(p);
597	
598	    // Check if this paragraph is followed by a setext heading underline
599	    // MD_SETEXT_UNDERLINE_LITERAL is for `=` underlines
600	    // MD_THEMATIC_BREAK_LITERAL with only `-` is also a setext underline (H2)
601	    let completed = if allow_setext && p.at(MD_SETEXT_UNDERLINE_LITERAL) {
602	        let indent = real_line_indent_from_source(p);
603	        if indent < INDENT_CODE_BLOCK_SPACES {
604	            // This is a setext heading (H1 with `=`) - consume the underline
605	            p.bump(MD_SETEXT_UNDERLINE_LITERAL);
606	            m.complete(p, MD_SETEXT_HEADER)
607	        } else {
608	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
609	            m.complete(p, MD_PARAGRAPH)
610	        }
611	    } else if allow_setext && p.at(MD_THEMATIC_BREAK_LITERAL) && is_dash_only_thematic_break(p) {
612	        let indent = real_line_indent_from_source(p);
613	        if indent < INDENT_CODE_BLOCK_SPACES {
614	            // This is a setext heading (H2 with `-`) - remap token and consume
615	            p.bump_remap(MD_SETEXT_UNDERLINE_LITERAL);
616	            m.complete(p, MD_SETEXT_HEADER)
617	        } else {
618	            // 4+ spaces of indent: not a setext underline (CommonMark §4.3)
619	            m.complete(p, MD_PARAGRAPH)
620	        }
621	    } else {
622	        m.complete(p, MD_PARAGRAPH)
623	    };
624	    Present(completed)
625	}
