}", "newString": "fn parse_code_block_newline(p: &mut MarkdownParser, depth: usize) -> bool {
    // Decide, without consuming, whether the following line continues the code
    // block (still indented after the quote prefix, or a blank line within it).
    // We must NOT consume the next line's quote prefix unless it actually
    // continues the code block; otherwise a following block (e.g. a thematic
    // break `> ---`) would be orphaned outside the quote.
    let continues = p.lookahead(|p| {
        if !has_quote_prefix(p, depth) {
            return false;
        }
        consume_quote_prefix_without_virtual(p, depth);
        p.at(NEWLINE) || at_quote_indented_code_start(p)
    });

    let text_m = p.start();
    p.bump_remap(MD_TEXTUAL_LITERAL);
    text_m.complete(p, MD_TEXTUAL);

    if p.at(T![EOF]) {
        return false;
    }

    if !continues {
        // Leave the next line's quote prefix intact so the quote block list can
        // parse it as a new block inside the quote.
        return false;
    }

    consume_quote_prefix(p, depth);

    // Blank lines (consecutive newlines) are allowed in indented code
    if p.at(NEWLINE) {
        return true;
    }

    // Next line must still be indented to continue the code block
    at_quote_indented_code_start(p)
